// apps/mobile/src/screens/RlcCopilotScreen.tsx
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  FlatList,
  Image,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  SafeAreaView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { COLORS } from "../ui/theme";
import { useFocusEffect, useNavigation, useRoute } from "@react-navigation/native";
import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import type { RouteProp } from "@react-navigation/native";

import type { RootStackParamList } from "../navigation/types";
import { api, getApiUrl } from "../lib/api";
import { getToken } from "../lib/auth";
import { Audio } from "expo-av";
import * as Speech from "expo-speech";
import * as FileSystem from "expo-file-system/legacy";

type Nav = NativeStackNavigationProp<RootStackParamList>;
type Rt = RouteProp<RootStackParamList, "RlcCopilot">;

type CopilotMode = "idle" | "listening" | "speaking" | "analyzing";

type Msg = {
  id: string;
  role: "user" | "assistant";
  text: string;
};

export const RLC_COPILOT_KI_AVATAR_SRC = "data:image/webp;base64,";

function uid() {
  return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function s(v: any) {
  return String(v ?? "").trim();
}

function firstText(obj: any): string {
  return s(
    obj?.answer ??
      obj?.text ??
      obj?.message ??
      obj?.reply ??
      obj?.data?.answer ??
      obj?.data?.text ??
      obj?.data?.message ??
      obj?.transcript
  );
}

function copilotModeLabel(mode: CopilotMode) {
  switch (mode) {
    case "listening":
      return "Ich h\u00F6re zu";
    case "speaking":
      return "Ich spreche";
    case "analyzing":
      return "Ich pr\u00FCfe";
    default:
      return "bereit";
  }
}

async function callMobileCopilot(payload: any): Promise<string> {
  const anyApi = api as any;
  const tries = [
    () => anyApi.mobileCopilotChat?.(payload),
    () => anyApi.askRlcCopilot?.(payload),
    () => anyApi.askSupportChat?.(payload.message, payload),
  ];

  for (const fn of tries) {
    try {
      const res = await fn();
      const t = firstText(res);
      if (t) return t;
    } catch {}
  }

  throw new Error("RLC Copilot ist gerade nicht erreichbar.");
}

function localMobileAnswer(text: string, projectCode?: string) {
  const q = text.toLowerCase();
  const p = projectCode ? ` im Projekt ${projectCode}` : "";

  if (q.includes("kalkulation")) {
    return `Auf Mobile \u00F6ffne ich die Kalkulation${p}. Dort siehst du die gespeicherte Server-Kalkulation, EP/GP je Position, Pr\u00FCffilter und den Outlier-Zugang. Neu berechnen l\u00E4uft nur mit Best\u00E4tigung \u00FCber den Server.`;
  }
  if (q.includes("outlier") || q.includes("risiko") || q.includes("pr\u00FCf")) {
    return `Auf Mobile findest du die Risiken im Outlier Report${p}. Dort werden pr\u00FCfpflichtige Positionen, fehlende Preise und auff\u00E4llige Gesamtpreise angezeigt.`;
  }
  if (q.includes("regie")) {
    return `F\u00FCr Regieberichte gehst du in der Mobile-App auf Regiebericht. Dort erfasst du Leistungen, Material, Ger\u00E4te, Fotos und Unterschrift direkt f\u00FCr das Projekt.`;
  }
  if (q.includes("lieferschein") || q.includes("ls")) {
    return `F\u00FCr Lieferscheine nutzt du auf Mobile den Bereich Lieferschein. Fotos oder PDFs werden zur Eingangspr\u00FCfung gesendet und mit der richtigen Baustelle verkn\u00FCpft.`;
  }
  if (q.includes("foto") || q.includes("notiz")) {
    return `Fotos und Notizen erfasst du mobil \u00FCber \u201EFotos / Notizen\u201C. Die KI kann sie projektbezogen auswerten, aber sie ersetzt keine finale fachliche Pr\u00FCfung.`;
  }

  return `Ich bin der RLC Copilot auf Mobile${p}. Ich kann dich durch Kalkulation, Outlier, Regiebericht, Lieferschein, Fotos, Mengenermittlung und Projektfunktionen f\u00FChren. Frag mich direkt, was du \u00F6ffnen oder pr\u00FCfen willst.`;
}

export default function RlcCopilotScreen() {
  const navigation = useNavigation<Nav>();
  const route = useRoute<Rt>();
  const params: any = route.params || {};

  const projectId = s(params.projectId);
  const projectCode = s(params.projectCode || params.projectId);
  const title = s(params.title || params.projectTitle || "RLC KI");
  const entryScreen = s(params.screen || "RlcCopilot");
  const initialMessage = s(params.initialMessage);

  const [input, setInput] = useState("");
  const [messages, setMessages] = useState<Msg[]>(() => [
    {
      id: uid(),
      role: "assistant",
      text: `RLC KI bereit${projectCode ? ` f\u00FCr ${projectCode}` : ""}. Ich bin die zentrale KI der Mobile-App: Chat, Projektf\u00FChrung, Kalkulation, Outlier, Regie, Lieferscheine, Fotos, Mikrofon und Sprachausgabe.`,
    },
  ]);
  const [busy, setBusy] = useState(false);
  const [mode, setMode] = useState<CopilotMode>("idle");
  const speechRunIdRef = useRef(0);
  const lastAssistantTextRef = useRef("");
  const [voiceEnabled, setVoiceEnabled] = useState(true);
  const [recording, setRecording] = useState<any | null>(null);
  const [recordingBusy, setRecordingBusy] = useState(false);

  const listRef = useRef<FlatList<Msg>>(null);
  const soundRef = useRef<any | null>(null);
  const recordingRef = useRef<any | null>(null);
  const recordingBusyRef = useRef(false);

  const context = useMemo(
    () => ({
      source: "rlc-mobile-copilot",
      platform: Platform.OS,
      screen: entryScreen,
      projectId,
      projectCode,
      title,
      mobileCapabilities: [
        "Kalkulation lesen",
        "KI-Kalkulation serverseitig starten",
        "Outlier Report \u00F6ffnen",
        "Regiebericht \u00F6ffnen",
        "Lieferschein \u00F6ffnen",
        "Fotos/Notizen \u00F6ffnen",
        "Mengenermittlung \u00F6ffnen",
        "Projektkontext erkl\u00E4ren",
        "Mikrofon und Sprachausgabe",
      ],
      importantRule:
        "Antworte konkret f\u00FCr die Mobile-App. Nicht allgemein \u00FCber Web reden. Kalkulation wird auf dem Server gespeichert und Mobile liest den Server-Snapshot.",
    }),
    [entryScreen, projectCode, projectId, title]
  );

  const scrollEnd = useCallback(() => {
    setTimeout(() => listRef.current?.scrollToEnd?.({ animated: true }), 80);
  }, []);

  useEffect(scrollEnd, [messages.length, scrollEnd]);

  useEffect(() => {
    if (initialMessage) {
      setTimeout(() => send(initialMessage), 250);
    }
    return () => {
      try {
        soundRef.current?.unloadAsync?.();
      } catch {}
      try {
        recordingRef.current?.stopAndUnloadAsync?.();
        recordingRef.current = null;
      } catch {}
      try {
        Speech.stop();
      } catch {}
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const navigateMobile = useCallback(
    async (target: string) => {
      const common: any = {
        projectId: projectCode || projectId,
        projectCode: projectCode || undefined,
        title,
      };

      switch (target) {
        case "Kalkulation":
          navigation.navigate("Kalkulation" as any, common);
          return;
        case "KiCalculation":
          navigation.navigate("KiCalculation" as any, {
            ...common,
            title: "KI-Kalkulation",
          });
          return;
        case "Outlier":
          navigation.navigate("KalkulationOutlier" as any, {
            ...common,
            title: "Outlier Report",
          });
          return;
        case "Regie":
          navigation.navigate("Regie" as any, common);
          return;
        case "Lieferschein":
          navigation.navigate("Lieferschein" as any, common);
          return;
        case "PhotosNotes":
          navigation.navigate("PhotosNotes" as any, common);
          return;
        case "Mengen":
          navigation.navigate("MengenList" as any, common);
          return;
        default:
          return;
      }
    },
    [navigation, projectCode, projectId, title]
  );

  const resolveNavigationCommand = useCallback((text: string) => {
    const q = text.toLowerCase();
    const wants =
      /(\u00F6ffne|oeffne|open|zeige|zeig|geh|gehe|navigiere|bring|porta|portami|apri|vai)/i.test(
        text
      );

    if (!wants) return null;
    if (q.includes("outlier") || q.includes("risik")) return "Outlier";
    if (q.includes("ki-kalk") || q.includes("ki kalk") || q.includes("neu berechnen")) return "KiCalculation";
    if (q.includes("kalkulation")) return "Kalkulation";
    if (q.includes("regie")) return "Regie";
    if (q.includes("lieferschein") || q.includes("ls")) return "Lieferschein";
    if (q.includes("foto") || q.includes("notiz")) return "PhotosNotes";
    if (q.includes("menge") || q.includes("aufma\u00DF") || q.includes("aufmass")) return "Mengen";
    return null;
  }, []);

  async function speak(text: string, force = false) {
    const clean = s(text).replace(/\s+/g, " ").slice(0, 1400);
    if (!clean || (!voiceEnabled && !force)) return;

    const runId = ++speechRunIdRef.current;
    try { Speech.stop(); } catch {}
    setMode("speaking");

    // 1) Professionelle Server-TTS wie Web.
    try {
      if (FileSystem.cacheDirectory && FileSystem.writeAsStringAsync) {
        const base = await getApiUrl();
        const token = await getToken().catch(() => "");
        const res = await fetch(`${base}/api/copilot/tts`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
          body: JSON.stringify({ text: clean, voice: "coral" }),
        });

        if (!res.ok) throw new Error(`TTS ${res.status}`);
        const arr = new Uint8Array(await res.arrayBuffer());

        let binary = "";
        const chunk = 0x8000;
        for (let i = 0; i < arr.length; i += chunk) {
          const part = arr.subarray(i, i + chunk);
          binary += String.fromCharCode.apply(null, Array.from(part) as any);
        }

        const globalAny: any = globalThis as any;
        const b64 =
          typeof globalAny.btoa === "function"
            ? globalAny.btoa(binary)
            : globalAny.Buffer?.from(binary, "binary")?.toString("base64");

        if (!b64) throw new Error("Base64 nicht verf\u00FCgbar.");

        const uri = `${FileSystem.cacheDirectory}rlc-copilot-tts-${Date.now()}.mp3`;
        await FileSystem.writeAsStringAsync(uri, b64, {
          encoding: FileSystem.EncodingType.Base64,
        });

        try {
          await soundRef.current?.unloadAsync?.();
        } catch {}

        const created = await Audio.Sound.createAsync({ uri });
        soundRef.current = created.sound;
        created.sound.setOnPlaybackStatusUpdate?.((st: any) => {
          if (st?.didJustFinish) setMode("idle");
        });
        await created.sound.playAsync();
        return;
      }
    } catch {}

    // 2) Fallback: lokale Expo Speech, falls Server-Audio nicht verf\u00FCgbar ist.
    try {
      Speech.stop();
      Speech.speak(clean, {
        language: "de-DE",
        rate: 0.96,
        pitch: 1.0,
        onDone: () => { if (speechRunIdRef.current === runId) setMode("idle"); },
        onStopped: () => { if (speechRunIdRef.current === runId) setMode("idle"); },
        onError: () => { if (speechRunIdRef.current === runId) setMode("idle"); },
      });
      return;
    } catch {}

    setMode("idle");
  }

  async function send(text?: string) {
    const content = s(text ?? input);
    if (!content || busy) return;

    setInput("");
    setMessages((prev) => [...prev, { id: uid(), role: "user", text: content }]);
    setBusy(true);
    setMode("analyzing");

    try {
      const navTarget = resolveNavigationCommand(content);
      let answer = "";

      if (navTarget) {
        await navigateMobile(navTarget);
        answer = localMobileAnswer(content, projectCode);
      } else {
        try {
          answer = await callMobileCopilot({
            message: content,
            projectId,
            projectCode,
            title,
            entryMode: "RlcCopilot",
            context,
          });
        } catch {
          answer = localMobileAnswer(content, projectCode);
        }
      }

      setMessages((prev) => [...prev, { id: uid(), role: "assistant", text: answer }]);
      lastAssistantTextRef.current = answer;
      await speak(answer);
    } finally {
      setBusy(false);
      if (mode !== "speaking") setMode("idle");
    }
  }

  async function quick(_label: string, command: string) {
    await send(command);
  }

  async function toggleMic() {
    if (recordingBusyRef.current) return;

    const active = recordingRef.current || recording;
    if (active) {
      await stopRecording();
      return;
    }

    recordingBusyRef.current = true;
    setRecordingBusy(true);

    try {
      try {
        await recordingRef.current?.stopAndUnloadAsync?.();
      } catch {}
      recordingRef.current = null;
      setRecording(null);

      const perm = await Audio.requestPermissionsAsync();
      if (!perm?.granted) {
        Alert.alert("Mikrofon", "Mikrofonberechtigung wurde nicht erteilt.");
        return;
      }

      await Audio.setAudioModeAsync?.({
        allowsRecordingIOS: true,
        playsInSilentModeIOS: true,
        staysActiveInBackground: false,
      });

      const rec = new Audio.Recording();
      recordingRef.current = rec;

      await rec.prepareToRecordAsync(Audio.RecordingOptionsPresets.HIGH_QUALITY);
      await rec.startAsync();

      setRecording(rec);
      setMode("listening");
    } catch (e: any) {
      try {
        await recordingRef.current?.stopAndUnloadAsync?.();
      } catch {}
      recordingRef.current = null;
      setRecording(null);
      setMode("idle");
      Alert.alert("Mikrofon", e?.message || "Aufnahme konnte nicht gestartet werden.");
    } finally {
      recordingBusyRef.current = false;
      setRecordingBusy(false);
    }
  }

  async function stopRecording() {
    if (recordingBusyRef.current) return;

    const rec = recordingRef.current || recording;
    if (!rec) {
      setRecording(null);
      setMode("idle");
      return;
    }

    recordingBusyRef.current = true;
    setRecordingBusy(true);
    setMode("analyzing");

    try {
      try {
        await rec.stopAndUnloadAsync?.();
      } catch (stopErr: any) {
        const msg = String(stopErr?.message || "");
        if (!msg.toLowerCase().includes("already been unloaded")) throw stopErr;
      }

      const uri = rec.getURI?.();
      recordingRef.current = null;
      setRecording(null);

      await Audio.setAudioModeAsync?.({
        allowsRecordingIOS: false,
        playsInSilentModeIOS: true,
        staysActiveInBackground: false,
        shouldDuckAndroid: true,
        playThroughEarpieceAndroid: false,
      } as any);

      if (!uri) throw new Error("Keine Audiodatei erzeugt.");

      const base = await getApiUrl();
      const token = await getToken().catch(() => "");

      const body = new FormData();
      body.append("audio" as any, {
        uri,
        name: `rlc-mobile-copilot-${Date.now()}.m4a`,
        type: "audio/m4a",
      } as any);
      body.append("projectCode" as any, projectCode as any);
      body.append("screen" as any, "RlcCopilot" as any);

      const res = await fetch(`${base}/api/copilot/stt`, {
        method: "POST",
        headers: {
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body,
      });

      const json = await res.json().catch(() => null);
      const text = firstText(json);

      if (!res.ok || !text) {
        throw new Error(json?.error || "Spracherkennung nicht verf\u00FCgbar.");
      }

      setInput(text);
      await send(text);
    } catch (e: any) {
      recordingRef.current = null;
      setRecording(null);
      Alert.alert(
        "Spracherkennung",
        e?.message ||
          "Die Aufnahme wurde erstellt, aber der Server konnte sie nicht in Text umwandeln."
      );
    } finally {
      recordingBusyRef.current = false;
      setRecordingBusy(false);
      setMode("idle");
    }
  }

  function stopAudio() {
    speechRunIdRef.current += 1;
    try {
      soundRef.current?.stopAsync?.();
      soundRef.current?.unloadAsync?.();
      soundRef.current = null;
    } catch {}
    try {
      Speech.stop();
    } catch {}
    setMode("idle");
  }

  // RLC_STOP_AUDIO_ON_BLUR_V1
  useFocusEffect(
    useCallback(() => {
      return () => {
        try {
          soundRef.current?.stopAsync?.();
          soundRef.current?.unloadAsync?.();
          soundRef.current = null;
        } catch {}
        try {
          Speech.stop();
        } catch {}
        setMode("idle");
      };
    }, [])
  );

  const canSend = !!s(input) && !busy;

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView
        style={styles.flex}
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        keyboardVerticalOffset={Platform.OS === "ios" ? 92 : 0}
      >
        <View style={styles.top}>
          <View style={styles.avatarWrap}>
            <Image source={{ uri: RLC_COPILOT_KI_AVATAR_SRC }} style={styles.avatar} />
            <View
              style={[
                styles.modeDot,
                mode === "listening" && styles.modeListening,
                mode === "speaking" && styles.modeSpeaking,
                mode === "analyzing" && styles.modeAnalyzing,
              ]}
            />
          </View>
          <View style={styles.topText}>
            <Text style={styles.title}>RLC KI</Text>
            <Text style={styles.sub}>
              {projectCode || "Mobile"} \u00B7 {copilotModeLabel(mode)}
            </Text>
          </View>
          <Pressable
            style={[styles.smallBtn, mode === "speaking" && styles.smallBtnStop]}
            onPress={() => {
              if (mode === "speaking" || voiceEnabled) {
                stopAudio();
                setVoiceEnabled(false);
                return;
              }

              setVoiceEnabled(true);
              const last = s(lastAssistantTextRef.current);
              if (last) setTimeout(() => speak(last, true), 80);
            }}
          >
            <Text style={styles.smallBtnTxt}>
              {mode === "speaking" ? "Stop" : voiceEnabled ? "Audio an" : "Audio aus"}
            </Text>
          </Pressable>
        </View>

        <View style={styles.quickBar}>
          <FlatList
            horizontal
            showsHorizontalScrollIndicator={false}
            data={[
              ["Projekt pr\u00FCfen", "Analysiere dieses mobile Projekt konkret."],
              ["Kalkulation", "\u00D6ffne Kalkulation und erkl\u00E4re mir die gespeicherte Server-Kalkulation."],
              ["Outlier", "\u00D6ffne Outlier Report und erkl\u00E4re die Risiken."],
              ["Regie", "\u00D6ffne Regiebericht."],
              ["Lieferschein", "\u00D6ffne Lieferschein."],
              ["Fotos", "\u00D6ffne Fotos und Notizen."],
            ]}
            keyExtractor={(x) => x[0]}
            renderItem={({ item }) => (
              <Pressable style={styles.quick} onPress={() => quick(item[0], item[1])}>
                <Text style={styles.quickTxt}>{item[0]}</Text>
              </Pressable>
            )}
          />
        </View>

        <FlatList
          ref={listRef}
          style={styles.messages}
          contentContainerStyle={styles.messagesContent}
          keyboardShouldPersistTaps="handled"
          data={messages}
          keyExtractor={(m) => m.id}
          renderItem={({ item }) => (
            <View
              style={[
                styles.bubble,
                item.role === "user" ? styles.userBubble : styles.assistantBubble,
              ]}
            >
              <Text style={item.role === "user" ? styles.userText : styles.assistantText}>
                {item.text}
              </Text>
            </View>
          )}
          onContentSizeChange={scrollEnd}
        />

        <View style={styles.inputRow}>
          <Pressable
            style={[
              styles.micBtn,
              recording && styles.micBtnActive,
              recordingBusy && styles.micBtnBusy,
              mode === "speaking" && styles.micBtnSpeaking,
            ]}
            onPress={mode === "speaking" ? stopAudio : toggleMic}
            disabled={(busy && !recording && mode !== "speaking") || recordingBusy}
          >
            <Text style={styles.micTxt}>
              {recordingBusy ? "\u2026" : mode === "speaking" ? "STOP" : recording ? "REC" : "MIC"}
            </Text>
          </Pressable>

          <TextInput
            value={input}
            onChangeText={setInput}
            onFocus={scrollEnd}
            placeholder="RLC KI fragen\u2026"
            placeholderTextColor={COLORS.sub}
            style={styles.input}
            multiline
            editable={!busy}
            returnKeyType="send"
            onSubmitEditing={() => send()}
          />

          <Pressable
            style={[styles.sendBtn, !canSend && styles.sendBtnDisabled]}
            onPress={() => send()}
            disabled={!canSend}
          >
            {busy ? (
              <ActivityIndicator color={COLORS.card} />
            ) : (
              <Text style={styles.sendTxt}>Senden</Text>
            )}
          </Pressable>
        </View>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

