  quickBar: {
    paddingVertical: 12,
    paddingLeft: 14,
    borderBottomWidth: 1,
    borderBottomColor: COLORS.border,
    backgroundColor: COLORS.inputBg,
  },
  quick: {
    marginRight: 9,
    paddingHorizontal: 16,
    paddingVertical: 10,
    borderRadius: 999,
    backgroundColor: COLORS.card,
    borderWidth: 1,
    borderColor: COLORS.border,
  },
  quickTxt: { color: COLORS.text, fontWeight: "900", fontSize: 14 },
